public class Main {
    private int base = 10;

    class Adder {
        int add(int x) {
            return base + x;
        }
    }

    public static void main(String[] args) {
        Main outer = new Main();
        Main.Adder adder = outer.new Adder();
        System.out.println(adder.add(5));
        outer.base = 100;
        System.out.println(adder.add(5));
    }
}
